head.script:
scwin.gIsurCd;
scwin.gImprRegDd;
scwin.gImprRegDd2;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // showObj(txb_isurcd, false);    // 히든처리!
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(penel_1);
        scwin.setCode();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_file_save",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_file_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 파일: 가우스헤더 셋팅

        // dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_fileData.insertRow();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35117.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.getValue());
        txb_file_nm.setValue(inf_find.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35117.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("등록 성공");
        $c.frame.path("../").fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35117.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert("등록 실패");
        await $c.win.alert(trs_Save.ErrorMsg);
        // alert(dts_C_All.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35117.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name img_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35117.img_save_onclick" });
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35117.img_close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 등록
    // 초기화
    dts_file_save.removeAll();
    if (scwin.gIsurCd === "") {
        await $c.win.alert("벌점입력화면에서 법인을 조회 후 등록가능합니다.");
        return;
    }
    if (txb_file_nm.getValue() === "") {
        await $c.win.alert("첨부파일을  입력해주세요");
        inf_find.focus();
        return;
    }
    if (txb_file_nm.getValue().length > 80) {
        await $c.win.alert("첨부파일명 길이 80자리를 초과했습니다.");
        txb_file_nm.focus();
        return;
    }
    dts_file_save.insertRow();
    dts_file_save.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_file_save.setCellData(1, "REG_EMP_NO", js_emp_no);
    dts_file_save.setCellData(1, "ATTACH_FILE_NM", txb_file_nm.getValue());
    dts_file_save.setCellData(1, "LD_MKT_TP_CD", js_market);

    // 2015.10.26 이민철

    let vAnswer;
    let vmethod;
    vAnswer = confirm('내부정보관리의무 제정ㆍ공표의무 이행내역을 저장 하시겠습니까?');
    // vmethod = "registerImprSchdlFile";
    vmethod = "registerPerfmDtlFile";
    if (vAnswer === true) {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/PenaltyImposition.do",
            ref : "dts_file_save,dts_fileData",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // gIsurCd = frame.Provider("../").txb_isurcd.value;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    // 계획서 구분(01: 개선계획서, 02: 이행보고서)

    edt_reg_dd.setValue($c.ut.cGetToday("yyyymmdd"));
    txb_emp_nm.setValue(js_emp_nm);
};
